import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../../../app/atlas_academy_app.dart';

class AdminClinicalCasesScreen extends StatefulWidget{const AdminClinicalCasesScreen({super.key});@override State<AdminClinicalCasesScreen> createState()=>_AdminClinicalCasesScreenState();}
class _AdminClinicalCasesScreenState extends State<AdminClinicalCasesScreen>{
 final db=FirebaseFirestore.instance;bool authorized=false,checking=true;
 @override void initState(){super.initState();_check();}
 Future<void> _check()async{final u=FirebaseAuth.instance.currentUser;bool ok=false;if(u!=null){try{ok=(await u.getIdTokenResult(true)).claims?['admin']==true;}catch(_){}}if(mounted)setState((){authorized=ok;checking=false;});}
 Future<void> _form({String? id,Map<String,dynamic>? data})async{
 final d=data??{};final title=TextEditingController(text:(d['title']??'').toString()),specialty=TextEditingController(text:(d['specialty']??'').toString()),difficulty=TextEditingController(text:(d['difficulty']??'Intermediate').toString()),summary=TextEditingController(text:(d['summary']??'').toString()),scenario=TextEditingController(text:(d['scenario']??'').toString()),history=TextEditingController(text:(d['history']??'').toString()),vitals=TextEditingController(text:(d['vitals']??'').toString()),investigations=TextEditingController(text:(d['investigations']??'').toString()),findings=TextEditingController(text:(d['findings']??'').toString()),management=TextEditingController(text:(d['management']??'').toString()),question=TextEditingController(text:(d['questions'] is List?(d['questions'] as List).map((q)=>'${q['question']}|${(q['options'] as List? ?? []).join('~')}|${q['correctAnswer']}|${q['explanation']}').join('\n'):''));
 bool published=d['isPublished']==true;final key=GlobalKey<FormState>();
 await showDialog(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:Text(id==null?'Create clinical case':'Edit clinical case'),content:SizedBox(width:600,child:SingleChildScrollView(child:Form(key:key,child:Column(mainAxisSize:MainAxisSize.min,children:[
  _field(title,'Case title',required:true),_field(specialty,'Specialty / subject',required:true),_field(difficulty,'Difficulty'),_field(summary,'Short case summary',lines:2),_field(scenario,'Patient presentation / scenario',lines:4),_field(history,'History and examination',lines:4),_field(vitals,'Vitals',lines:3),_field(investigations,'Investigations / lab results',lines:4),_field(findings,'Clinical findings',lines:4),_field(management,'Management, learning points and debrief',lines:5),_field(question,'Decision questions: question|optionA~optionB~optionC~optionD|correct letter|explanation (one per line)',lines:5),
  SwitchListTile(value:published,onChanged:(v)=>setD(()=>published=v),title:const Text('Publish to eligible students')),
 ])))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()async{if(!key.currentState!.validate())return;final qs=<Map<String,dynamic>>[];for(final line in question.text.split('\n')){if(line.trim().isEmpty)continue;final parts=line.split('|');if(parts.length<4)continue;final opts=parts[1].split('~').map((x)=>x.trim()).where((x)=>x.isNotEmpty).toList();final correct=parts[2].trim().toUpperCase();if(opts.length==4&&['A','B','C','D'].contains(correct)){qs.add({'question':parts[0].trim(),'options':opts,'correctAnswer':correct,'explanation':parts.sublist(3).join('|').trim()});}}
 final payload={'title':title.text.trim(),'specialty':specialty.text.trim(),'difficulty':difficulty.text.trim(),'summary':summary.text.trim(),'scenario':scenario.text.trim(),'history':history.text.trim(),'vitals':vitals.text.trim(),'investigations':investigations.text.trim(),'findings':findings.text.trim(),'management':management.text.trim(),'questions':qs,'isPublished':published,'updatedAt':FieldValue.serverTimestamp(),'updatedBy':FirebaseAuth.instance.currentUser?.uid};try{if(id==null){payload['createdAt']=FieldValue.serverTimestamp();payload['createdBy']=FirebaseAuth.instance.currentUser?.uid;await db.collection('clinical_cases').add(payload);}else{await db.collection('clinical_cases').doc(id).update(payload);}if(ctx.mounted)Navigator.pop(ctx);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Clinical case saved.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Save failed: $e')));}},child:const Text('Save case'))])));
 }
 Widget _field(TextEditingController c,String label,{int lines=1,bool required=false})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextFormField(controller:c,minLines:lines,maxLines:lines==1?1:lines,validator:required?(v)=>v==null||v.trim().isEmpty?'Required':null:null,decoration:InputDecoration(labelText:label,alignLabelWithHint:true)));
 Future<void> _delete(String id)async{await db.collection('clinical_cases').doc(id).delete();}
 @override Widget build(BuildContext context){if(checking)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(!authorized)return const Scaffold(body:Center(child:Text('Administrator access required.')));return Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('Clinical Case Management')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_form(),icon:const Icon(Icons.add),label:const Text('Create case')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection('clinical_cases').snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text('Error: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs;if(docs.isEmpty)return const Center(child:Text('No clinical cases created yet.'));return ListView(padding:const EdgeInsets.all(15),children:[Container(padding:const EdgeInsets.all(17),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AtlasColors.navy,AtlasColors.royalBlue]),borderRadius:BorderRadius.circular(18)),child:const Text('Build structured clinical scenarios with history, examination, investigations, decision questions, explanations and a management debrief. Drafts stay private until published.',style:TextStyle(color:Colors.white,height:1.5))),const SizedBox(height:13),...docs.map((doc){final d=doc.data();return Card(child:ListTile(title:Text((d['title']??'Untitled case').toString(),style:const TextStyle(color:AtlasColors.navy,fontWeight:FontWeight.w900)),subtitle:Text('${d['specialty']??'General'} • ${d['isPublished']==true?'Published':'Draft'}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='edit')_form(id:doc.id,data:d);if(v=='delete')_delete(doc.id);if(v=='publish')db.collection('clinical_cases').doc(doc.id).update({'isPublished':d['isPublished']!=true,'updatedAt':FieldValue.serverTimestamp()});},itemBuilder:(_)=>[const PopupMenuItem(value:'edit',child:Text('Edit')),PopupMenuItem(value:'publish',child:Text(d['isPublished']==true?'Unpublish':'Publish')),const PopupMenuItem(value:'delete',child:Text('Delete'))])));})]);}));}
}

class AdminStudentSupportScreen extends StatefulWidget{const AdminStudentSupportScreen({super.key});@override State<AdminStudentSupportScreen> createState()=>_AdminStudentSupportScreenState();}
class _AdminStudentSupportScreenState extends State<AdminStudentSupportScreen>{
 final db=FirebaseFirestore.instance;bool authorized=false,checking=true;
 @override void initState(){super.initState();_check();}
 Future<void> _check()async{final u=FirebaseAuth.instance.currentUser;bool ok=false;if(u!=null){try{ok=(await u.getIdTokenResult(true)).claims?['admin']==true;}catch(_){}}if(mounted)setState((){authorized=ok;checking=false;});}
 Future<void> _reply(String id,Map<String,dynamic>d)async{final c=TextEditingController(text:(d['reply']??'').toString());final v=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Teacher response'),content:TextField(controller:c,minLines:3,maxLines:7,decoration:const InputDecoration(hintText:'Write an educational response…')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:const Text('Send reply'))]));if(v!=null&&v.isNotEmpty){await db.collection('teacher_questions').doc(id).update({'reply':v,'status':'answered','repliedBy':FirebaseAuth.instance.currentUser?.uid,'repliedAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()});}}
 Future<void> _moderate(String id,String status)async{await db.collection('forum_posts').doc(id).update({'status':status,'moderatedBy':FirebaseAuth.instance.currentUser?.uid,'moderatedAt':FieldValue.serverTimestamp()});}
 @override Widget build(BuildContext context){if(checking)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(!authorized)return const Scaffold(body:Center(child:Text('Administrator access required.')));return DefaultTabController(length:2,child:Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('Student Community & Support'),bottom:const TabBar(tabs:[Tab(text:'Teacher questions'),Tab(text:'Discussion moderation')])),body:TabBarView(children:[
  StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection('teacher_questions').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=[...s.data!.docs]..sort((a,b)=>(b.data()['createdAt'] as Timestamp? ?? Timestamp(0,0)).compareTo(a.data()['createdAt'] as Timestamp? ?? Timestamp(0,0)));return ListView(padding:const EdgeInsets.all(14),children:docs.map((doc){final d=doc.data();return Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${d['subject']??'Question'} • ${d['studentName']??'Student'}',style:const TextStyle(color:AtlasColors.royalBlue,fontWeight:FontWeight.w900)),const SizedBox(height:7),Text((d['question']??'').toString(),style:const TextStyle(color:AtlasColors.charcoal,height:1.5)),if((d['reply']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Text('Current reply: ${d['reply']}',style:const TextStyle(color:AtlasColors.success))),Align(alignment:Alignment.centerRight,child:FilledButton.icon(onPressed:()=>_reply(doc.id,d),icon:const Icon(Icons.reply),label:Text(d['status']=='answered'?'Update reply':'Reply')))])));}).toList());}),
  StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection('forum_posts').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=[...s.data!.docs]..sort((a,b)=>(b.data()['createdAt'] as Timestamp? ?? Timestamp(0,0)).compareTo(a.data()['createdAt'] as Timestamp? ?? Timestamp(0,0)));return ListView(padding:const EdgeInsets.all(14),children:docs.map((doc){final d=doc.data();return Card(child:ListTile(title:Text((d['title']??'').toString(),style:const TextStyle(color:AtlasColors.navy,fontWeight:FontWeight.w900)),subtitle:Text('${d['authorName']??'Student'} • ${d['status']??'published'}\n${d['body']??''}'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v)=>_moderate(doc.id,v),itemBuilder:(_)=>[const PopupMenuItem(value:'published',child:Text('Approve / publish')),const PopupMenuItem(value:'hidden',child:Text('Hide')),const PopupMenuItem(value:'removed',child:Text('Remove'))])));}).toList());})
 ])));}
}
